import{_ as e,c as r,o as a,ae as o}from"./chunks/framework.CliRSA9F.js";const n="/images/chart_rankings.webp",d=JSON.parse('{"title":"My Charts","description":"","frontmatter":{},"headers":[],"relativePath":"features/my-charts.md","filePath":"features/my-charts.md"}'),s={name:"features/my-charts.md"};function i(l,t,h,c,g,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="my-charts" tabindex="-1">My Charts <a class="header-anchor" href="#my-charts" aria-label="Permalink to &quot;My Charts&quot;">​</a></h1><h2 id="see-which-charts-feature-your-podcast" tabindex="-1">See Which Charts Feature Your Podcast <a class="header-anchor" href="#see-which-charts-feature-your-podcast" aria-label="Permalink to &quot;See Which Charts Feature Your Podcast&quot;">​</a></h2><p>My Charts shows you exactly which platform podcast charts your podcast appears on right now, along with its rank on each one. It pulls together your chart placements across the major listening platforms so you can see your competitive position at a glance and track how each placement has moved over time.</p><p><img src="'+n+'" alt="My Charts Dashboard" width="600px" style="display:block;margin:0 auto;"></p><h2 id="overview" tabindex="-1"><strong>Overview</strong> <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;**Overview**&quot;">​</a></h2><p>Chart placements are valuable indicators of podcast discoverability. My Charts lists the charts your podcast is currently featured on, grouped by platform, and gives you a count of your total chart placements. For each placement you can open a ranking history to see how your position has changed.</p><p>The data reflects a rolling 30-day window, so My Charts shows where you&#39;ve been charting recently — both the charts you&#39;re on now and any you&#39;ve slipped off in the past month.</p><h2 id="key-features" tabindex="-1"><strong>Key Features</strong> <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;**Key Features**&quot;">​</a></h2><h3 id="charts-grouped-by-platform" tabindex="-1"><strong>Charts Grouped by Platform</strong> <a class="header-anchor" href="#charts-grouped-by-platform" aria-label="Permalink to &quot;**Charts Grouped by Platform**&quot;">​</a></h3><p>Your placements are organized by the platform they belong to, so you can quickly see where you&#39;re charting:</p><ul><li><strong>Apple Podcasts</strong> - Current Apple Podcasts chart placements</li><li><strong>iTunes (Legacy)</strong> - Legacy iTunes charts, still maintained for podcasts that predate the Apple Podcasts relaunch</li><li><strong>Spotify</strong> - Your placements in Spotify&#39;s podcast charts</li><li><strong>Amazon Music</strong> - Rankings in Amazon Music&#39;s podcast charts</li><li><strong>YouTube Music</strong> - Your placements in YouTube Music podcast charts</li></ul><p>Each group is labeled with the platform and shows how many charts you appear on there.</p><h3 id="placement-details" tabindex="-1"><strong>Placement Details</strong> <a class="header-anchor" href="#placement-details" aria-label="Permalink to &quot;**Placement Details**&quot;">​</a></h3><p>Within each platform group, every chart placement shows:</p><ul><li><strong>Your rank</strong> - The position your podcast holds on that chart</li><li><strong>The country</strong> - Which country&#39;s chart it is, shown with a flag</li><li><strong>The chart name</strong> - The specific chart or category you&#39;re appearing on</li><li><strong>Recency</strong> - If you&#39;re no longer actively charting on a placement, you&#39;ll see when it was last seen (for example, &quot;Seen 3d ago&quot;)</li></ul><h3 id="ranking-history" tabindex="-1"><strong>Ranking History</strong> <a class="header-anchor" href="#ranking-history" aria-label="Permalink to &quot;**Ranking History**&quot;">​</a></h3><p>Click any chart row to open its ranking history. This reveals how your position on that specific chart has moved over the rolling window, so you can see whether a placement is trending up, holding steady, or slipping.</p><h2 id="how-to-use-my-charts" tabindex="-1"><strong>How to Use My Charts</strong> <a class="header-anchor" href="#how-to-use-my-charts" aria-label="Permalink to &quot;**How to Use My Charts**&quot;">​</a></h2><ol><li><strong>Review your placement count</strong> - The summary at the top tells you how many charts currently feature your podcast.</li><li><strong>Scan by platform</strong> - Work through the platform groups to understand where you&#39;re strongest and where you have placements you might not have noticed.</li><li><strong>Open a ranking history</strong> - Click any row to see how that placement has changed over time, which helps you connect movement to recent episodes or promotion.</li><li><strong>Watch for dropped placements</strong> - Rows marked with a &quot;last seen&quot; note are charts you&#39;ve recently fallen off, signaling where to focus next.</li></ol><h2 id="understanding-your-chart-data" tabindex="-1"><strong>Understanding Your Chart Data</strong> <a class="header-anchor" href="#understanding-your-chart-data" aria-label="Permalink to &quot;**Understanding Your Chart Data**&quot;">​</a></h2><h3 id="what-the-placements-tell-you" tabindex="-1"><strong>What the Placements Tell You</strong> <a class="header-anchor" href="#what-the-placements-tell-you" aria-label="Permalink to &quot;**What the Placements Tell You**&quot;">​</a></h3><ul><li><strong>Current rank</strong> - Where your podcast stands on each chart it appears on</li><li><strong>Platform spread</strong> - Which platforms are giving your podcast chart visibility</li><li><strong>Country reach</strong> - The country charts your podcast is landing on</li><li><strong>Recent momentum</strong> - Whether placements are holding or you&#39;ve recently dropped off</li></ul><h3 id="reading-ranking-history" tabindex="-1"><strong>Reading Ranking History</strong> <a class="header-anchor" href="#reading-ranking-history" aria-label="Permalink to &quot;**Reading Ranking History**&quot;">​</a></h3><p>The per-chart history helps you spot patterns:</p><ul><li><strong>Entry points</strong> - When your podcast first appeared on a chart</li><li><strong>Sustained performance</strong> - How long you&#39;ve held a placement</li><li><strong>Peaks</strong> - Your strongest position on a given chart</li><li><strong>Declines</strong> - When and how a placement started slipping</li></ul><h2 id="using-chart-data-for-strategy" tabindex="-1"><strong>Using Chart Data for Strategy</strong> <a class="header-anchor" href="#using-chart-data-for-strategy" aria-label="Permalink to &quot;**Using Chart Data for Strategy**&quot;">​</a></h2><h3 id="performance-analysis" tabindex="-1"><strong>Performance Analysis</strong> <a class="header-anchor" href="#performance-analysis" aria-label="Permalink to &quot;**Performance Analysis**&quot;">​</a></h3><ul><li><strong>Trend identification</strong> - Use ranking history to spot patterns in how your placements move</li><li><strong>Platform comparison</strong> - Understand which platforms give your content the most chart visibility</li><li><strong>Content correlation</strong> - Connect specific episodes or releases with changes in your chart placements</li></ul><h3 id="competitive-intelligence" tabindex="-1"><strong>Competitive Intelligence</strong> <a class="header-anchor" href="#competitive-intelligence" aria-label="Permalink to &quot;**Competitive Intelligence**&quot;">​</a></h3><ul><li><strong>Market position</strong> - Understand your competitive standing within the charts you appear on</li><li><strong>Opportunity identification</strong> - Notice charts where you&#39;re close to a stronger position</li><li><strong>Strategic planning</strong> - Use your placement data to inform content and promotion priorities</li></ul><h2 id="maximizing-chart-performance" tabindex="-1"><strong>Maximizing Chart Performance</strong> <a class="header-anchor" href="#maximizing-chart-performance" aria-label="Permalink to &quot;**Maximizing Chart Performance**&quot;">​</a></h2><h3 id="content-strategy-for-charts" tabindex="-1"><strong>Content Strategy for Charts</strong> <a class="header-anchor" href="#content-strategy-for-charts" aria-label="Permalink to &quot;**Content Strategy for Charts**&quot;">​</a></h3><ul><li><strong>Release timing</strong> - Plan content releases to maximize chart impact</li><li><strong>Episode quality</strong> - Focus on content that drives sustained engagement</li><li><strong>Series planning</strong> - Develop content series that maintain chart momentum</li><li><strong>Audience engagement</strong> - Build loyal audiences that support consistent chart performance</li></ul><h3 id="building-on-your-placements" tabindex="-1"><strong>Building on Your Placements</strong> <a class="header-anchor" href="#building-on-your-placements" aria-label="Permalink to &quot;**Building on Your Placements**&quot;">​</a></h3><ul><li><strong>Reinforce strengths</strong> - Promote the charts where you&#39;re already performing well</li><li><strong>Pursue near-misses</strong> - Focus effort where your rank is close to a meaningful threshold</li><li><strong>Recover dropped placements</strong> - Use the &quot;last seen&quot; signals to identify charts worth winning back</li></ul><blockquote><p><strong>Advanced SEO Strategy</strong>: Chart appearances create authority signals that benefit your podcast&#39;s overall search performance. Podcasts that regularly appear in charts often see improved search rankings and organic discovery across platforms.</p></blockquote><h2 id="chart-performance-indicators" tabindex="-1"><strong>Chart Performance Indicators</strong> <a class="header-anchor" href="#chart-performance-indicators" aria-label="Permalink to &quot;**Chart Performance Indicators**&quot;">​</a></h2><h3 id="strong-chart-performance" tabindex="-1"><strong>Strong Chart Performance</strong> <a class="header-anchor" href="#strong-chart-performance" aria-label="Permalink to &quot;**Strong Chart Performance**&quot;">​</a></h3><ul><li><strong>Consistent appearances</strong> - Regular presence across relevant charts</li><li><strong>Upward trends</strong> - Improving positions in your ranking history</li><li><strong>Multiple platform success</strong> - Placements across different platforms</li><li><strong>Category strength</strong> - Strong rank in relevant genre charts</li></ul><h3 id="opportunities-for-improvement" tabindex="-1"><strong>Opportunities for Improvement</strong> <a class="header-anchor" href="#opportunities-for-improvement" aria-label="Permalink to &quot;**Opportunities for Improvement**&quot;">​</a></h3><ul><li><strong>Inconsistent performance</strong> - Sporadic placements that could be stabilized</li><li><strong>Single platform focus</strong> - Success on one platform that could be expanded</li><li><strong>Recently dropped charts</strong> - Placements you&#39;ve slipped off that could be recovered</li></ul><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><h3 id="seo-and-discovery" tabindex="-1"><strong>SEO and Discovery</strong> <a class="header-anchor" href="#seo-and-discovery" aria-label="Permalink to &quot;**SEO and Discovery**&quot;">​</a></h3><ul><li><strong>Search performance</strong> - Chart success supports overall search rankings and discoverability</li><li><strong>Keyword strategy</strong> - Use chart performance to inform keyword and content strategy</li><li><strong>Competitive analysis</strong> - Compare your placements with competitors for strategic insight</li></ul><h3 id="performance-monitoring" tabindex="-1"><strong>Performance Monitoring</strong> <a class="header-anchor" href="#performance-monitoring" aria-label="Permalink to &quot;**Performance Monitoring**&quot;">​</a></h3><ul><li><strong>Audience insights</strong> - Use chart data to understand audience preferences</li><li><strong>Content strategy</strong> - Inform future content decisions based on chart performance patterns</li></ul><p><strong>Related Features</strong>: My Charts works closely with <a href="/features/all-charts.html">All Charts</a>, where you can browse every chart by platform and country to find the placements you could climb next. It also pairs well with the Planner&#39;s metadata alignment for optimizing chart-driving content and Competitive Analysis for understanding your position in the chart landscape.</p>',47)])])}const m=e(s,[["render",i]]);export{d as __pageData,m as default};
